var wg sync.WaitGroup

for _, u := range urls {
	wg.Add(1)              // BEFORE the go statement
	go func() {
		defer wg.Done()    // deferred, so a panic still counts
		fetch(u)
	}()
}

wg.Wait()                      // blocks until the counter hits zero

func main() {
	go fmt.Println("hello")
	// main returns here
}
// prints nothing, usually

jobs := make(chan int, 10)

go func() {
	defer close(jobs)     // the SENDER closes
	for i := 0; i < 5; i++ {
		jobs <- i
	}
}()

for j := range jobs {     // ends when jobs is closed
	process(j)
}

type Counter struct {
	mu sync.Mutex
	n  map[string]int
}

func (c *Counter) Inc(k string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.n[k]++
}
